!function(){"use strict";const e=[{id:"thar-geography",title:"Geographic Location",content:"Located mostly in the state of Rajasthan, extending into Gujarat, Punjab, and Haryana. It forms a natural boundary between India and Pakistan."},{id:"thar-climate",title:"Climate & Temperature",content:"Arid and subtropical. Temperatures can soar up to 50°C (122°F) in summer and drop to near freezing 0°C (32°F) in winter."},{id:"thar-landscape",title:"Sand Dunes & Terrain",content:"Characterized by vast, shifting sand dunes (barchans, longitudinal, and transverse), rocky outcrops, and sparse salt lakes."},{id:"thar-flora",title:"Native Flora",content:"<ul><li>Khejri Tree (State tree of Rajasthan)</li><li>Rohida</li><li>Various thorny bushes and drought-resistant cacti</li></ul>"},{id:"thar-fauna",title:"Native Fauna",content:"<ul><li>Great Indian Bustard (Critically Endangered)</li><li>Blackbuck</li><li>Indian Gazelle (Chinkara)</li><li>Desert Fox</li></ul>"},{id:"thar-communities",title:"Communities & Culture",content:"Home to tribes like the Bishnois (known for fierce conservation of trees and animals), Bhils, and nomadic pastoralists. Rich in folk music, colorful attire, and camel herding."},{id:"thar-adaptations",title:"Survival Adaptations",content:"Plants have deep taproots and waxy leaves to minimize water loss. Animals like the camel store fat in humps, and many rodents are nocturnal to avoid the daytime heat. Traditional architecture uses thick mud walls to keep interiors cool."}],t=[{id:"spiti-geography",title:"Geographic Location",content:"Located in the Himalayas in the northern state of Himachal Pradesh (Spiti) and the Union Territory of Ladakh. These are high-altitude regions lying in the rain shadow of the Himalayas."},{id:"spiti-climate",title:"Climate & Temperature",content:"Harsh, cold arid climate. Summer temperatures range from 15°C to 25°C, while winter plummets to -20°C to -40°C (-40°F)."},{id:"spiti-landscape",title:"Rocky Landscapes",content:"Barren, jagged mountains, deep gorges, scree slopes, and high-altitude lakes (like Pangong Tso). Almost entirely devoid of sand dunes (except localized ones like in Hunder, Nubra Valley)."},{id:"spiti-flora",title:"Native Flora",content:"<ul><li>Seabuckthorn (vital for soil erosion and local economy)</li><li>Alpine scrubs</li><li>Wild roses and junipers along river banks</li></ul>"},{id:"spiti-fauna",title:"Native Fauna",content:"<ul><li>Snow Leopard (Ghost of the mountains)</li><li>Himalayan Ibex</li><li>Tibetan Wolf</li><li>Bactrian Camel (double-humped)</li></ul>"},{id:"spiti-communities",title:"Communities & Culture",content:"Predominantly Buddhist culture with ancient monasteries (Key, Tabo, Hemis) perched on cliffs. Communities rely on agriculture during the short summer and pastoralism."},{id:"spiti-adaptations",title:"Survival Adaptations",content:"Animals have thick coats of fur (e.g., Pashmina goats, Yaks). Houses are built with flat roofs for drying crops and thick mud/stone walls to retain heat. Agriculture depends heavily on glacier meltwater via traditional irrigation channels (Kuhls)."}],a=document.getElementById("thar-content"),i=document.getElementById("spiti-content"),n=document.getElementById("theme-toggle");function o(e,t){t.forEach(t=>{const a=document.createElement("div");a.className="accordion-item",a.innerHTML=`\n                <button class="accordion-btn" aria-expanded="false" aria-controls="${t.id}-panel" id="${t.id}-btn">\n                    <span>${t.title}</span>\n                    <span class="accordion-icon" aria-hidden="true">▼</span>\n                </button>\n                <div class="accordion-panel" id="${t.id}-panel" role="region" aria-labelledby="${t.id}-btn">\n                    <div class="accordion-inner">\n                        ${t.content}\n                    </div>\n                </div>\n            `;const i=a.querySelector(".accordion-btn"),n=a.querySelector(".accordion-panel");i.addEventListener("click",()=>{const t="true"===i.getAttribute("aria-expanded");!function(e){const t=e.querySelectorAll(".accordion-btn"),a=e.querySelectorAll(".accordion-panel");t.forEach(e=>e.setAttribute("aria-expanded","false")),a.forEach(e=>e.style.maxHeight=null)}(e),t||(i.setAttribute("aria-expanded","true"),n.style.maxHeight=n.scrollHeight+"px")}),e.appendChild(a)})}function l(e){n.innerHTML="dark-theme"===e?"☀️ Light Mode":"🌙 Dark Mode"}document.addEventListener("DOMContentLoaded",()=>{o(a,e),o(i,t),function(){const e=localStorage.getItem("theme")||"light-theme";document.body.className=e,l(e),n.addEventListener("click",()=>{const e="light-theme"===(document.body.classList.contains("light-theme")?"light-theme":"dark-theme")?"dark-theme":"light-theme";document.body.className=e,localStorage.setItem("theme",e),l(e)})}()})}();